import type { DbType } from '@/types';
import { computed } from 'vue';

const props = defineProps<{
  type: DbType | string;
  size?: number | string;
}>();

const iconSize = computed(() => {
  if (!props.size) return '1em';
  const s = String(props.size);
  if (/^\d+$/.test(s)) return `${s}px`;
  return s;
});

// Professional color palette for DB types - made slightly brighter for dark theme visibility
const dbColors: Record<string, string> = {
  postgresql: '#417EAF', // Brighter Postgres Blue
  mysql: '#00758F', // MySQL Blue
  sqlite: '#003B57', // SQLite Navy
  oracle: '#F80000', // Oracle Red
  sqlserver: '#CC2927', // SQL Server Red
  mariadb: '#003545', // MariaDB Dark Blue
  redis: '#D82C20' // Redis Red
};

const normalizedType = computed(() => String(props.type).toLowerCase());
const color = computed(() => dbColors[normalizedType.value] || 'currentColor');
</script>

